// Le rapport du matin porte sur les ventes de la veille : on calcule la date
// et le chemin du CSV attendu (produit par le générateur, spec 01), monté dans
// /data à la fois ici et côté service loader.
const dateVeille = $today.minus({ days: 1 }).toFormat('yyyy-MM-dd');

return [
  {
    json: {
      date_veille: dateVeille,
      csv_path: `/data/export_${dateVeille}.csv`,
    },
  },
];

// Assemblage HTML du rapport (spec 05) : CA en grand, flèches colorées selon
// le signe, tableaux top 5, CA par région avec mini-barres en CSS (bonus
// graphique sans dépendance externe à un service de chart en ligne),
// bandeau d'alerte business si kpi_alerte_chute est vrai.
const row = $input.first().json;

const ca = row.ca_veille;
const j7 = row.comparaison_j7;
const mois = row.comparaison_moyenne_mois;
const topClients = row.top_clients || [];
const topProduits = row.top_produits || [];
const region = row.ca_region || [];
const alerte = row.alerte_chute;

const euros = (n) =>
  Number(n).toLocaleString('fr-FR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';

const couleur = (ecart) => (ecart >= 0 ? '#1a7f37' : '#c0392b');
const fleche = (ecart) => (ecart >= 0 ? '▲' : '▼');

const ligneComparaison = (label, valeurRef, ecartValeur, ecartPourcent) => `
  <tr>
    <td style="padding:4px 8px;color:#6b7280;">${label} (${euros(valeurRef)})</td>
    <td style="padding:4px 8px;text-align:right;color:${couleur(ecartValeur)};font-weight:bold;">${fleche(ecartValeur)} ${ecartPourcent}%</td>
  </tr>`;

const ligneTableau = (items, labelKey) =>
  items
    .map(
      (i) => `
    <tr>
      <td style="padding:4px 8px;border-bottom:1px solid #e5e7eb;">${i[labelKey]}</td>
      <td style="padding:4px 8px;border-bottom:1px solid #e5e7eb;text-align:right;">${euros(i.ca)}</td>
    </tr>`
    )
    .join('');

const maxRegionCa = Math.max(...region.map((r) => Number(r.ca)), 1);
const barresRegion = region
  .map((r) => {
    const largeur = Math.round((Number(r.ca) / maxRegionCa) * 100);
    return `
    <tr>
      <td style="padding:4px 8px;width:30%;">${r.region}</td>
      <td style="padding:4px 8px;">
        <div style="background:#e5e7eb;border-radius:3px;">
          <div style="background:#2563eb;color:#fff;font-size:11px;padding:2px 6px;border-radius:3px;width:${largeur}%;min-width:28px;white-space:nowrap;">${euros(r.ca)}</div>
        </div>
      </td>
    </tr>`;
  })
  .join('');

const bandeauAlerte =
  alerte && alerte.alerte
    ? `<div style="background:#fdecea;border-left:4px solid #c0392b;color:#c0392b;padding:10px 14px;font-weight:bold;margin-bottom:16px;">⚠ Alerte : CA en forte baisse (${alerte.ecart_pourcent}% vs J-7)</div>`
    : '';

const html = `
<html>
<body style="font-family: Arial, sans-serif; color:#222; max-width:600px; margin:0 auto;">
${bandeauAlerte}
<p style="color:#6b7280;margin:0 0 2px 0;">CA de la veille — ${ca.date_veille}</p>
<p style="font-size:34px;font-weight:bold;margin:0 0 12px 0;">${euros(ca.ca)}</p>
<table style="border-collapse:collapse;margin-bottom:20px;">
  ${ligneComparaison('vs J-7', j7.ca_j7, j7.ecart_valeur, j7.ecart_pourcent)}
  ${ligneComparaison('vs moyenne du mois', mois.ca_moyen_mois, mois.ecart_valeur, mois.ecart_pourcent)}
</table>

<h2 style="font-size:16px;border-bottom:2px solid #222;padding-bottom:4px;">Top 5 clients</h2>
<table style="border-collapse:collapse;width:100%;margin-bottom:20px;">${ligneTableau(topClients, 'cli_nom')}</table>

<h2 style="font-size:16px;border-bottom:2px solid #222;padding-bottom:4px;">Top 5 produits</h2>
<table style="border-collapse:collapse;width:100%;margin-bottom:20px;">${ligneTableau(topProduits, 'art_lib')}</table>

<h2 style="font-size:16px;border-bottom:2px solid #222;padding-bottom:4px;">CA par région</h2>
<table style="border-collapse:collapse;width:100%;margin-bottom:20px;">${barresRegion}</table>

<p style="color:#9ca3af;font-size:11px;margin-top:24px;">Données fictives — projet de démonstration, aucun gain de temps réel mesuré.</p>
</body>
</html>
`;

return [{ json: { subject: `Rapport commercial — ${ca.date_veille}`, html } }];

// Branche erreur (spec 04/05) : gabarit volontairement distinct du rapport
// normal (bandeau plein, pas de tableaux), jamais de chiffres faux ou à zéro.
const row = $input.first().json;
const reason = row.reason || 'raison inconnue';

const html = `
<html>
<body style="font-family: Arial, sans-serif; margin:0; padding:0; background:#f3f4f6;">
<div style="max-width:600px;margin:0 auto;">
  <div style="background:#c0392b;color:#fff;padding:16px 20px;font-size:20px;font-weight:bold;">⚠ Rapport non généré</div>
  <div style="background:#fff;padding:20px;color:#222;">
    <p>Le rapport commercial automatique n'a pas pu être généré ce matin.</p>
    <p><strong>Raison :</strong> ${reason}</p>
    <p style="color:#9ca3af;font-size:11px;margin-top:24px;">Projet de démonstration — données fictives.</p>
  </div>
</div>
</body>
</html>
`;

return [{ json: { subject: 'ALERTE — Rapport non généré', html } }];
